begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
set local search_path=pgtap,extensions,public;
select plan(39);
select has_function('public','update_customer',array['uuid','uuid','jsonb'],'customer update RPC exists');
select has_function('public','update_sales_quotation',array['uuid','uuid','date','jsonb','jsonb','jsonb','text','text'],'draft quotation update RPC exists');

insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values
('00000000-0000-4000-8000-00000000400a','00000000-0000-0000-0000-000000000000','authenticated','authenticated','sales-owner@example.test','',now(),now(),now()),
('00000000-0000-4000-8000-00000000400b','00000000-0000-0000-0000-000000000000','authenticated','authenticated','sales-outsider@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000400a","role":"authenticated"}',true);
select lives_ok($$select public.create_organization('Sales Test','sales-test','GB','GBP','Europe/London')$$,'sales tenant bootstraps');
set local role postgres;
select set_config('s.org',(select id::text from public.organizations where slug='sales-test'),true);
select set_config('s.business',(select id::text from public.businesses where organization_id=current_setting('s.org')::uuid limit 1),true);
select set_config('s.unit',(select id::text from public.units_of_measure where organization_id=current_setting('s.org')::uuid and name='Piece'),true);
select set_config('s.price_list',(select id::text from public.price_lists where organization_id=current_setting('s.org')::uuid and is_default),true);
insert into public.branches(id,organization_id,business_id,name,code,status,timezone,created_by) values('00000000-0000-4000-8000-000000004101',current_setting('s.org')::uuid,current_setting('s.business')::uuid,'Sales Branch','SALE','active','Europe/London','00000000-0000-4000-8000-00000000400a');
insert into public.warehouses(id,organization_id,business_id,branch_id,name,code,status,warehouse_type,created_by) values('00000000-0000-4000-8000-000000004201',current_setting('s.org')::uuid,current_setting('s.business')::uuid,'00000000-0000-4000-8000-000000004101','Sales Main','SALE-M','active','MAIN','00000000-0000-4000-8000-00000000400a');
select set_config('s.loc',(select id::text from public.storage_locations where warehouse_id='00000000-0000-4000-8000-000000004201' limit 1),true);
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000400a","role":"authenticated"}',true);
select set_config('s.product',(select public.create_simple_product(current_setting('s.org')::uuid,current_setting('s.business')::uuid,'Sales Item','STOCKED_PRODUCT',null,null,null,current_setting('s.unit')::uuid,'SALE-1','',null,null,null,null,true,gen_random_uuid())::text),true);
set local role postgres;select set_config('s.variant',(select id::text from public.product_variants where product_id=current_setting('s.product')::uuid),true);select set_config('s.package',(select id::text from public.product_variant_packaging where product_variant_id=current_setting('s.variant')::uuid and is_base_unit),true);
insert into public.product_prices(organization_id,price_list_id,product_variant_id,packaging_id,min_quantity,amount,created_by) values(current_setting('s.org')::uuid,current_setting('s.price_list')::uuid,current_setting('s.variant')::uuid,current_setting('s.package')::uuid,1,20,'00000000-0000-4000-8000-00000000400a');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000400a","role":"authenticated"}',true);
select lives_ok(format($q$select public.post_inventory_transaction('%s','%s','OPENING_STOCK',now(),null,'Sales opening',null,'00000000-0000-4000-8000-000000004301',jsonb_build_array(jsonb_build_object('product_variant_id','%s','packaging_id','%s','storage_location_id','%s','quantity',20,'unit_cost',10)))$q$,current_setting('s.org'),current_setting('s.business'),current_setting('s.variant'),current_setting('s.package'),current_setting('s.loc')),'opening stock posts');
select set_config('s.customer',(select public.create_customer(current_setting('s.org')::uuid,jsonb_build_object('customer_code','CUS-1','customer_type','BUSINESS','display_name','Customer One','default_currency','GBP','default_price_list_id',current_setting('s.price_list'),'credit_limit',1000))::text),true);
select is((select status from public.customers where id=current_setting('s.customer')::uuid),'ACTIVE','customer created active');
select lives_ok(format($q$select public.update_customer('%s','%s',jsonb_build_object('display_name','Customer One Updated','customer_type','BUSINESS','default_currency','GBP','credit_limit',1000,'credit_status','NORMAL','status','ACTIVE'))$q$,current_setting('s.org'),current_setting('s.customer')),'customer updates through authorized RPC');
select lives_ok(format($q$select public.add_customer_contact('%s','%s',jsonb_build_object('name','Buyer One','email','buyer@example.test','is_primary',true))$q$,current_setting('s.org'),current_setting('s.customer')),'customer contact added through RPC');
select lives_ok(format($q$select public.add_customer_address('%s','%s',jsonb_build_object('address_type','DELIVERY','line_1','1 Test Street','city','London','country_code','GB','is_default_delivery',true))$q$,current_setting('s.org'),current_setting('s.customer')),'customer address added through RPC');
select is(public.resolve_sales_price(current_setting('s.org')::uuid,current_setting('s.price_list')::uuid,'00000000-0000-4000-8000-000000004101',current_setting('s.variant')::uuid,current_setting('s.package')::uuid,10),20::numeric,'deterministic price resolved');
select set_config('s.quote',(select public.create_sales_quotation(current_setting('s.org')::uuid,current_setting('s.business')::uuid,current_setting('s.customer')::uuid,'00000000-0000-4000-8000-000000004101',current_date+7,current_setting('s.price_list')::uuid,'GBP',1,null,null,jsonb_build_array(jsonb_build_object('product_variant_id',current_setting('s.variant'),'packaging_id',current_setting('s.package'),'quantity',10)),'Quote',null,'00000000-0000-4000-8000-000000004401')::text),true);
select is((select total from public.sales_quotations where id=current_setting('s.quote')::uuid),200::numeric,'quotation total calculated');
select is(public.transition_sales_quotation(current_setting('s.org')::uuid,current_setting('s.quote')::uuid,'SUBMIT'),'PENDING_APPROVAL','quotation submitted');
select is(public.transition_sales_quotation(current_setting('s.org')::uuid,current_setting('s.quote')::uuid,'APPROVE'),'APPROVED','quotation approved');
select is(public.transition_sales_quotation(current_setting('s.org')::uuid,current_setting('s.quote')::uuid,'ACCEPT'),'ACCEPTED','quotation accepted');
select set_config('s.order',(select public.convert_quotation_to_sales_order(current_setting('s.org')::uuid,current_setting('s.quote')::uuid,'00000000-0000-4000-8000-000000004201',current_setting('s.loc')::uuid,current_date+2,'00000000-0000-4000-8000-000000004402')::text),true);
select is((select count(*) from public.sales_orders where originating_quotation_id=current_setting('s.quote')::uuid),1::bigint,'quotation creates one order');
select is(public.convert_quotation_to_sales_order(current_setting('s.org')::uuid,current_setting('s.quote')::uuid,'00000000-0000-4000-8000-000000004201',current_setting('s.loc')::uuid,current_date+2,'00000000-0000-4000-8000-000000004402'),current_setting('s.order')::uuid,'conversion replay returns existing order');
select is((public.confirm_sales_order(current_setting('s.org')::uuid,current_setting('s.order')::uuid,true,false)->>'status'),'RESERVED','order confirmation reserves stock');
select is((select reserved_base_quantity from public.sales_order_lines where sales_order_id=current_setting('s.order')::uuid),10::numeric,'Sales reservation projection equals ten');
select is((select remaining_quantity from public.inventory_reservations where source_id=(select id from public.sales_order_lines where sales_order_id=current_setting('s.order')::uuid)),10::numeric,'inventory reservation is authoritative');
select set_config('s.order_line',(select id::text from public.sales_order_lines where sales_order_id=current_setting('s.order')::uuid),true);
select set_config('s.ful1',(select public.create_sales_fulfilment(current_setting('s.org')::uuid,current_setting('s.order')::uuid,jsonb_build_array(jsonb_build_object('sales_order_line_id',current_setting('s.order_line'),'quantity',4)),now(),'Partial','00000000-0000-4000-8000-000000004501')::text),true);
select lives_ok(format($q$select public.post_sales_fulfilment('%s','%s')$q$,current_setting('s.org'),current_setting('s.ful1')),'partial fulfilment posts atomically');
select is((select on_hand_base_quantity from public.inventory_balances where product_variant_id=current_setting('s.variant')::uuid),16::numeric,'partial SALE leaves sixteen on hand');
select is((select remaining_quantity from public.inventory_reservations where source_id=current_setting('s.order_line')::uuid),6::numeric,'partial fulfilment consumes four reserved');
select is((select fulfilled_base_quantity from public.sales_order_lines where id=current_setting('s.order_line')::uuid),4::numeric,'Sales line fulfilled projection is four');
select is((select inventory_cost_base from public.sales_fulfillment_lines where fulfilment_id=current_setting('s.ful1')::uuid),40::numeric,'fulfilment COGS comes from ledger');
select is((select gross_profit_base from public.sales_fulfillment_lines where fulfilment_id=current_setting('s.ful1')::uuid),40::numeric,'gross profit uses actual COGS');
select is((public.post_sales_fulfilment(current_setting('s.org')::uuid,current_setting('s.ful1')::uuid)->>'replayed')::boolean,true,'duplicate fulfilment replays without stock post');
select set_config('s.ful2',(select public.create_sales_fulfilment(current_setting('s.org')::uuid,current_setting('s.order')::uuid,jsonb_build_array(jsonb_build_object('sales_order_line_id',current_setting('s.order_line'),'quantity',6)),now(),'Remainder','00000000-0000-4000-8000-000000004502')::text),true);
select lives_ok(format($q$select public.post_sales_fulfilment('%s','%s')$q$,current_setting('s.org'),current_setting('s.ful2')),'remaining fulfilment posts');
select is((select status from public.sales_orders where id=current_setting('s.order')::uuid),'FULFILLED','order becomes fulfilled');
select is((select count(*) from public.inventory_transactions where reference_type='SALES_FULFILMENT' and reference_id in(current_setting('s.ful1')::uuid,current_setting('s.ful2')::uuid)),2::bigint,'exactly two SALE ledger postings');
select set_config('s.invoice',(select public.create_customer_invoice(current_setting('s.org')::uuid,current_setting('s.order')::uuid,array[current_setting('s.ful1')::uuid,current_setting('s.ful2')::uuid],current_date,current_date+30,'Invoice','00000000-0000-4000-8000-000000004601')::text),true);
select lives_ok(format($q$select public.issue_customer_invoice('%s','%s')$q$,current_setting('s.org'),current_setting('s.invoice')),'invoice issues');
select is((select on_hand_base_quantity from public.inventory_balances where product_variant_id=current_setting('s.variant')::uuid),10::numeric,'invoice issue creates no stock movement');
select is((select outstanding_base from public.customer_receivables where customer_id=current_setting('s.customer')::uuid),200::numeric,'issued invoice creates derived AR');
select set_config('s.return',(select public.create_sales_return(current_setting('s.org')::uuid,current_setting('s.ful1')::uuid,current_setting('s.invoice')::uuid,(select id from public.sales_return_reasons where organization_id=current_setting('s.org')::uuid and code='DEFECTIVE'),jsonb_build_array(jsonb_build_object('sales_fulfillment_line_id',(select id from public.sales_fulfillment_lines where fulfilment_id=current_setting('s.ful1')::uuid),'quantity',2)),'Return','00000000-0000-4000-8000-000000004701')::text),true);
select lives_ok(format($q$select public.inspect_sales_return('%s','%s',jsonb_build_array(jsonb_build_object('sales_return_line_id',(select id from public.sales_return_lines where sales_return_id='%s'),'received_quantity',2,'accepted_quantity',2,'rejected_quantity',0,'disposition','RESTOCK_NORMAL','destination_location_id','%s')))$q$,current_setting('s.org'),current_setting('s.return'),current_setting('s.return'),current_setting('s.loc')),'return inspection accepted');
select lives_ok(format($q$select public.post_sales_return('%s','%s')$q$,current_setting('s.org'),current_setting('s.return')),'sales return posts atomically');
select is((select on_hand_base_quantity from public.inventory_balances where product_variant_id=current_setting('s.variant')::uuid),12::numeric,'SALE_RETURN restores accepted stock');
select is((select sum(quantity_base*unit_cost_base) from public.sales_return_cost_allocations where sales_return_line_id=(select id from public.sales_return_lines where sales_return_id=current_setting('s.return')::uuid)),20::numeric,'return restores historical sold cost');
select is((select outstanding_base from public.customer_receivables where customer_id=current_setting('s.customer')::uuid),160::numeric,'return-linked credit reduces AR');
select throws_ok(format($q$select public.create_sales_return('%s','%s','%s',(select id from public.sales_return_reasons where organization_id='%s' and code='DEFECTIVE'),jsonb_build_array(jsonb_build_object('sales_fulfillment_line_id',(select id from public.sales_fulfillment_lines where fulfilment_id='%s'),'quantity',3)),'Over',gen_random_uuid())$q$,current_setting('s.org'),current_setting('s.ful1'),current_setting('s.invoice'),current_setting('s.org'),current_setting('s.ful1')),'P0001','RETURN_EXCEEDS_ELIGIBLE_QUANTITY','cumulative over-return blocked');
set local role anon;select set_config('request.jwt.claims','{"role":"anon"}',true);select throws_ok(format($q$select public.confirm_sales_order('%s','%s')$q$,current_setting('s.org'),current_setting('s.order')),'42501',null,'anon cannot invoke Sales confirmation');
set local role authenticated;select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-00000000400b","role":"authenticated"}',true);select throws_ok(format($q$select public.post_sales_fulfilment('%s','%s')$q$,current_setting('s.org'),current_setting('s.ful1')),'42501','PERMISSION_DENIED','cross-tenant outsider cannot post fulfilment');
select * from finish();rollback;
